import {services,conditions,medications,professionalPages} from './care-data.js';
import {serviceDetails,conditionDetails,medicationDetails} from './content-details.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=text=>`<p>${e(text)}</p>`;
const paragraphs=items=>items.map(p).join('');
const a=(href,text,cls='text-link')=>`<a class="${cls}" href="${e(href)}">${e(text)} <span aria-hidden="true">↗</span></a>`;
const list=items=>`<ul class="guide-list">${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`;
const section=(id,label,title,body)=>`<section class="wrap section guide-section" id="${id}"><div class="guide-heading"><p class="eyebrow">${e(label)}</p><h2>${e(title)}</h2></div>${body}</section>`;
const rows=items=>`<div class="guide-rows">${items.map(([title,text],i)=>`<article><span class="guide-number">${String(i+1).padStart(2,'0')}</span><div><h3>${e(title)}</h3>${p(text)}</div></article>`).join('')}</div>`;
const tiles=items=>`<div class="guide-tiles">${items.map(([title,text])=>`<article><h3>${e(title)}</h3>${p(text)}</article>`).join('')}</div>`;
const toc=items=>`<nav class="wrap guide-toc" aria-label="On this page"><span>On this page</span>${items.map(([id,title])=>`<a href="#${id}">${e(title)}</a>`).join('')}</nav>`;
const faqs=(items,id='questions')=>section(id,'Good questions','A little more clarity.',`<div class="faq-list guide-faq">${items.map(([q,answer])=>`<details><summary>${e(q)}</summary>${p(answer)}</details>`).join('')}</div>`);
const sources=(items,note='General educational information. A qualified clinician can discuss what applies to you.')=>`<aside class="wrap guide-sources"><p class="eyebrow">Read further</p>${p(note)}<div>${items.map(([url,title])=>a(url,title)).join('')}</div></aside>`;
function related(slugs){const items=conditions.filter(c=>slugs.includes(c.slug));return section('related','Continue exploring','A connected view of care.',`<div class="guide-related">${items.map(c=>`<a href="${c.path}"><span class="eyebrow">Understanding ${e(c.name)}</span><h3>${e(c.heading)}</h3>${p(c.description)}<span class="text-link">Read the guide ↗</span></a>`).join('')}</div>`);}
function nextStep(name='care'){return `<section class="wrap section"><div class="care-band"><div><p class="eyebrow">Your next step</p><h2>Start with a conversation.</h2><p>Explore ${e(name)} and tell us your preferences. The enquiry form is in testing mode and does not confirm an appointment.</p></div>${a('/get-started?service='+encodeURIComponent(name),'Explore your options','btn')}</div></section>`;}
export function careComparison(){return section('care-options','Choose a starting point','Different kinds of support.',`<div class="guide-comparison"><div class="comparison-head"><span>Care option</span><span>What the conversation can cover</span><span>Explore</span></div>${[['Individual therapy','Space for your own experiences, patterns, relationships, and goals.','/online-therapy'],['Couples therapy','A shared conversation about connection, conflict, and the direction of a relationship.','/online-therapy/couples-therapy'],['Teen therapy','Age-appropriate support with caregiver involvement and clear confidentiality boundaries.','/online-therapy/teens'],['Psychiatry','A medical assessment of mental health concerns and discussion of treatment options, including medication when appropriate.','/psychiatry']].map(([title,text,path])=>`<div><h3>${title}</h3><p>${text}</p>${a(path,'Learn more')}</div>`).join('')}</div><p class="guide-footnote">You do not need to choose perfectly before asking a question. Provider experience, clinical suitability, and your preferences help shape the next step.</p>`);}
function journey(){return section('first-steps','How to begin','A clear path, one step at a time.',rows([['Explore what fits','Read about the service or concern you have in mind. It is also fine to start with “I am not sure.” Think about language, location, and whether you would prefer online or in-person care.'],['Ask practical questions','Use the test enquiry experience to share basic preferences. Before real care begins, confirm the provider, appointment format, fees, privacy arrangements, and any consent requirements.'],['Agree on the work together','In a clinical appointment, discuss your priorities and the proposed approach. Ask how the plan will be reviewed and who to contact about questions between sessions.']]));}
function formats(){return section('formats','Care and everyday life','Choose the setting thoughtfully.',`<div class="guide-format"><img src="/assets/journal.jpg" alt="A quiet setting for reflection and preparation" width="650" height="500" loading="lazy"><div>${tiles([['Online appointments','Consider a private room, reliable connection, headphones, and time before and after the conversation. Confirm the clinician’s location requirements and whether remote care suits your needs.'],['In-person appointments','Ask about the clinic location, accessibility, travel time, and any arrangements for a support person. Some concerns require an in-person assessment even if you prefer online care.']])}<p class="guide-footnote">Available formats are provider-specific. This website does not host video calls or live appointment booking.</p></div></div>`);}
function servicePage(s,hero){const d=serviceDetails[s.slug];return hero+toc([['overview','About this care'],['areas','What you can explore'],['sessions','Your sessions'],['questions','FAQs']])+section('overview','Understanding '+s.name,s.heading,`<div class="guide-prose two-column">${paragraphs(d.intro)}</div>`)+section('areas','Your experience','What you might bring to therapy.',tiles(d.focus))+section('sessions','Inside the conversation','What working together can look like.',`<div class="guide-editorial"><img src="${s.image}" alt="A calm space for a thoughtful conversation" loading="lazy" width="600" height="600"><div class="guide-prose">${paragraphs(d.session)}<div class="guide-prompt"><span class="eyebrow">A question to bring</span><p>“What would working on my goals look like with you?”</p></div></div></div>`)+journey()+formats()+faqs(d.faqs.concat([['What will it cost?','Fees, session length, cancellation terms, and any extra charges need to be confirmed with the provider before you book. Stillwell has not published a fee schedule or promised insurance reimbursement.']]))+related(d.related)+nextStep(s.name);}
function conditionPage(c,hero){const d=conditionDetails[c.slug];const source=c.slug==='postpartum-depression'?'https://www.nimh.nih.gov/health/publications/perinatal-depression':c.source;return hero+toc([['understanding','Understanding it'],['signs','What to notice'],['support','Support options'],['questions','FAQs']])+section('understanding','Understanding '+c.name,'Look at the whole picture.',`<div class="guide-prose two-column">${p(d.overview)}${p('A condition name can be useful for learning, but it cannot describe your entire experience. Assessment considers the impact on your life, the context in which changes happened, and what support is already in place. You can bring uncertainty to the conversation rather than arriving with a conclusion.')}</div>`)+section('signs','Patterns to discuss','What may be worth noticing.',`<div class="guide-symptoms"><div>${list(d.signs)}</div><aside><h3>A starting point, not a diagnosis.</h3><p>These examples are not a scoring tool or a complete diagnostic checklist. Similar experiences can have different explanations. Describe the duration, intensity, and effect on your everyday life to a qualified professional.</p></aside></div>`)+section('support','Assessment and care','Support should fit the person.',`<div class="guide-prose">${p(d.approach)}</div>${tiles([['Understanding your needs','Ask what the assessment will cover, whether physical health or another specialist needs to be involved, and how the clinician reached their recommendation.'],['Making the plan practical','Discuss language, accessibility, existing care, time, and financial constraints. A useful plan should be understandable and workable in your circumstances.'],['Reviewing the direction','Agree on what to look for between appointments and when to review progress. Raise concerns about the approach or unwanted effects rather than waiting for a routine milestone.']])}`)+section('prepare','Before your appointment','Bring your experience, in your own words.',`<div class="guide-editorial guide-editorial-text"><div class="guide-prose">${p(d.context)}${a('/get-started','Ask about an assessment','btn')}</div><div class="guide-question-list">${c.questions.map((q,i)=>`<p><span>0${i+1}</span>${e(q)}</p>`).join('')}</div></div>`)+faqs(d.faq)+section('next-options','Explore care','Find the right kind of conversation.',tiles([['Psychological support','Explore individual therapy and ask about relevant training and experience with the concern you want to address.'],['Medical assessment','Explore psychiatry when a medical evaluation or medication discussion may be appropriate. An enquiry does not establish a diagnosis.']])+`<div class="guide-actions">${a('/online-therapy','Individual therapy')}${a('/psychiatry','Psychiatry')}${a('/therapists','Provider directory')}</div>`)+sources([[source,'Clinical information: '+(source.includes('nimh')?'NIMH':'NHS')]])+nextStep(c.name);}
function medicationPage(m,header){const d=medicationDetails[m.slug];const safety=['abilify','buspar','lithium','propranolol'].includes(m.slug)?'Ask your prescriber which effects need urgent attention, what monitoring is required, and how to get help between appointments. This summary is not a complete list of warnings or interactions.':'Antidepressants carry warnings about new or worsening suicidal thoughts, particularly in younger people and around treatment changes. Contact a healthcare professional promptly about concerning changes. Immediate danger needs emergency care. This is not a complete safety list.';return header+toc([['medicine-overview','About the medicine'],['medicine-review','Assessment'],['medicine-safety','Safety & follow-up'],['questions','FAQs']])+section('medicine-overview','A guide to '+m.name,'Understand the reason for treatment.',`<div class="guide-editorial guide-editorial-text"><div class="guide-prose">${p(d.use)}<p>Brand names on this page help you recognise information you may have seen elsewhere. They do not confirm a particular brand’s availability, licensing, or approved uses in India. Ask a local prescriber or pharmacist about the exact product.</p></div><aside class="medicine-cover"><span class="eyebrow">Medicine information</span><svg viewBox="0 0 180 100" aria-hidden="true"><g transform="rotate(-25 90 50)"><rect x="35" y="25" width="110" height="50" rx="25" fill="none" stroke="currentColor" stroke-width="2"/><path d="M90 25v50M35 50h55" fill="none" stroke="currentColor" stroke-width="2"/></g></svg><h3>${e(m.name)}</h3><p>${e(m.group)}</p><small>Information, not a prescription</small></aside></div>`)+section('medicine-review','Your consultation','The assessment comes before the choice.',rows([['Your history and priorities','Prepare to discuss what has changed, previous treatment, physical health, and what you hope treatment will address. A medicine name is a starting point for questions, not a predetermined outcome.'],['The options and the trade-offs','Ask why a medicine is being considered, what alternatives exist, and what follow-up would involve. The clinician should explain the plan in language you understand.'],['A practical follow-up plan','Clarify how to arrange reviews, obtain advice about problems, and handle questions about the prescription. Record the instructions given by your treating professional.']]))+section('medicine-safety','Safety and follow-up','Know what to ask. Know who to contact.',`<div class="guide-prose">${p(d.watch)}<p class="guide-clinical-note">${e(safety)}</p></div><div class="guide-prompt"><span class="eyebrow">Ask your prescriber</span>${p(d.question)}</div>`)+section('appointment-notes','Prepare for the conversation','Keep the useful details together.',tiles([['Current medicines','Bring the names of prescription medicines, over-the-counter products, vitamins, and supplements. Ask the professional how to share this information securely.'],['Previous experiences','Note any treatments you have tried, why they were stopped, and questions you still have. A concise timeline can be easier to discuss than recalling everything at once.'],['Everyday priorities','Mention work, driving, caregiving, sleep routines, and other practical concerns that you want considered in a treatment discussion.']]))+faqs([['Can I get this medicine by filling in the enquiry form?','No. The website stores test enquiries only. Prescribing requires an appropriate clinical assessment and a decision by a qualified prescriber. No medicine is sold or dispatched through Stillwell’s website.'],['Does this page provide a dose or a treatment schedule?','No. Follow the instructions for your own prescription and formulation. Ask your prescriber or pharmacist about any uncertainty rather than using a general website to change treatment.'],['Are consultation and medicine costs the same?','They may be separate. Ask about consultation fees, follow-up fees, the price of the medicine, and any tests before proceeding. No price or reimbursement is guaranteed here.'],['Where can I read the full medicine information?','Use the source guide linked below and the information supplied with your actual medicine. The source is US-based, so discuss local prescribing and product details with an Indian clinician or pharmacist.']])+related(d.related)+sources([[m.source,'MedlinePlus: '+m.name],...(m.slug==='propranolol'?[['https://www.nhs.uk/medicines/propranolol/about-propranolol/','NHS: propranolol']]:[])],'Read the full medicine information and discuss it with a qualified prescriber. Do not start, stop, or change medication using this page.')+nextStep('Psychiatry');}

const professionalDetails={
 '/join-our-network/therapist':{intro:'A useful professional profile helps a person understand your training, approach, languages, and the concerns you work with. Begin by introducing your own practice and the kinds of clients you are qualified to support. The enquiry is an expression of interest, not an offer of work.',title:'A practice built on clear expectations.',items:[['Professional background','Prepare your qualifications, relevant registration where applicable, training, supervision arrangements, and the boundaries of your clinical scope.'],['Your way of working','Describe your therapeutic approach in everyday language, the age groups you see, and the concerns for which you would refer someone elsewhere.'],['Practical arrangements','Discuss languages, location, formats, accessibility, and availability. Fees, payment arrangements, caseload, and contracts must be agreed separately.']],faq:[['Does submitting a form publish my profile?','No. Profiles are added by the administrator, checked, and published only after verification and permission. An enquiry does not create a directory listing.'],['Are earnings or referrals guaranteed?','No earnings, volume of referrals, or employment terms are promised here. Those arrangements must be discussed and documented individually.'],['Should I upload certificates in this form?','No. The test form has no credential-document upload. Provide a brief professional introduction; a suitable verification process must be agreed separately.']]},
 '/join-our-network/prescriber':{intro:'Psychiatric care needs clear clinical accountability, an appropriate assessment process, and continuity beyond a first consultation. Introduce your professional background and discuss the settings and populations in which you are qualified to practise. No prescribing capability is granted by submitting a form.',title:'Clinical judgement at the centre.',items:[['Qualifications and registration','Prepare details of medical qualifications, psychiatry training, and current professional registration for verification through the agreed process.'],['Assessment and follow-up','Discuss your approach to suitability for remote care, monitoring, clinical review, referrals, and situations that need in-person or urgent assessment.'],['Working arrangements','Clarify availability, location, records, consent, professional responsibilities, and fees before any clinical service arrangement begins.']],faq:[['Does this website issue prescriptions?','No. It provides information and test enquiries. It does not operate a prescribing or pharmacy service.'],['Can a profile be published without registration information?','The administrator must verify the provider. A psychiatrist profile cannot be published in this directory without registration information.'],['Are the platform’s clinical processes already agreed?','No. Records, prescribing, follow-up, and escalation processes must be established with the relevant professionals before clinical delivery.']]},
 '/join-our-network/referral':{intro:'If you know a mental health professional who may be interested in Stillwell, start with your own details or share the application page with them. A good introduction respects the other person’s privacy and lets them decide whether to take the conversation further.',title:'An introduction with permission.',items:[['Start with your relationship','Explain how you know the professional and why the connection may be relevant, without disclosing private personal or employment information.'],['Let the professional opt in','Share the application link directly with them. Do not upload their certificates, identification, private correspondence, or contact details without an agreed basis.'],['Keep expectations clear','A referral does not mean approval, employment, or automatic publication. Credentials and arrangements still need to be checked with the individual.']],faq:[['Is there a referral reward?','No reward or payment arrangement is advertised or promised. Any future programme would need its own clear terms.'],['Can I nominate myself?','Yes. Use the therapist or psychiatric-provider application page to introduce your own background.'],['Can I check whether someone was accepted?','Application information belongs to the applicant. Do not assume that a referrer will receive private updates about another person.']]},
 '/physicians':{intro:'A referral conversation should make the next step clearer without exposing a patient’s private history through a general website form. Start with the referring professional’s details and the type of coordination you are asking about. Clinical records and an actual handover require a separately agreed process.',title:'A careful handover starts before records move.',items:[['Clarify the purpose','Identify whether you are seeking information about assessment, psychological support, psychiatry, or care coordination. Keep the test enquiry free of patient identifiers.'],['Confirm consent and the destination','Before exchanging any clinical information, confirm the patient’s involvement and consent, the receiving professional, and a suitable secure channel.'],['Agree responsibility and follow-up','Clarify who is responsible for current care, how receipt is confirmed, and what happens if the referral is unsuitable or urgent. Sending a form does not transfer clinical responsibility.']],faq:[['Can I attach a case history?','No. Do not submit patient names, diagnoses, medical documents, or records through this test form.'],['Does this form confirm acceptance of a patient?','No. It is a professional test enquiry. Suitability, consent, availability, and handover need direct agreement before a referral is accepted.'],['Can I use this for an urgent referral?','No. Use the appropriate local urgent or emergency pathway. This form is not monitored as an emergency clinical channel.']]},
 '/partners/health-collective':{intro:'Mental health support can connect with workplaces, educational communities, local organisations, and other healthcare services. A thoughtful partnership begins with the people it aims to serve and a realistic understanding of what each organisation can provide.',title:'Make the purpose specific.',items:[['Define the community and need','Describe the organisation, the people you hope to reach, and the practical problem you want to address. Avoid sharing employee, student, or patient records in an initial enquiry.'],['Discuss the kind of collaboration','Explore whether the conversation concerns education, signposting, referral coordination, or another clearly defined activity. No programme is confirmed simply by submitting the form.'],['Agree scope and accountability','Clarify responsibilities, fees, privacy, consent, delivery, and how you would judge whether the work is useful before making public claims about a partnership.']],faq:[['Is Stillwell already partnered with my organisation?','No partnership should be assumed from this page. Ask your organisation and the Stillwell team to confirm any agreed arrangement.'],['Do you offer an employee assistance package?','No specific package, price, or service level is published here. Use the enquiry to describe what your organisation is exploring.'],['Can I submit information about staff or students?','No personal records are needed. Use your own professional contact details and keep the initial description at an organisational level.']]}
};
function professionalPage(page,base,header){const d=professionalDetails[page.path];return header+toc([['professional-fit','The conversation'],['process','Next steps'],['professional-form','Enquiry'],['questions','FAQs']])+section('professional-fit','Working with Stillwell',d.title,`<div class="guide-prose">${p(d.intro)}</div>${rows(d.items)}`)+section('process','A clear process','Introduce. Discuss. Agree.',tiles([['Introduce yourself','Use the test form to share your own professional contact details and a short description of the enquiry. No documents or sensitive records are needed.'],['Review the fit','Discuss qualifications, clinical scope, the intended service, or the proposed collaboration before assuming a working relationship.'],['Confirm the arrangements','Verification, permission, fees, contracts, and operating processes require separate agreement. This form does not activate a service or clinical handover.']]))+`<div id="professional-form">${base.slice(header.length)}</div>`+faqs(d.faq)+section('professional-links','Other ways to connect','Find the relevant conversation.',`<div class="topic-chips">${professionalPages.filter(x=>x.path!==page.path).map(x=>a(x.path,x.name,'')).join('')}</div>`);}

function hubExtra(path){
 if(path==='/services')return careComparison()+section('finding-fit','Find a connection','Choose more than a service label.',rows([['The experience you want to discuss','A service name helps organise information, but your goals may span work, relationships, sleep, or several concerns. Begin with the part of life you would most like to understand.'],['A provider’s relevant experience','Read qualifications, professional registration where applicable, and the provider’s stated areas of work. Ask about experience with your age group and the approach they would use.'],['A workable arrangement','Consider language, privacy, accessibility, fees, and appointment format. A practical fit matters alongside the clinical conversation.']]))+formats()+journey()+faqs([['Can I explore more than one service?','Yes. Reading about several options does not commit you to treatment. An initial professional conversation can help clarify the right starting point.'],['What if I am choosing for someone else?','You can help them find information, but use your own contact details and respect their privacy. A guardian starts teen enquiries. Do not submit another adult’s health history through a form.'],['Are all providers trained for every concern?','No. Training, experience, age groups, and clinical scope differ. Confirm the individual provider’s suitability rather than assuming that a service listing guarantees every specialty.']]);
 if(path==='/psychiatry')return section('assessment','A medical perspective','More than a medicine discussion.',`<div class="guide-prose two-column"><p>A psychiatric assessment considers your mental health concerns alongside physical health, history, medicines, sleep, everyday functioning, and current circumstances. It can help clarify what is happening and whether further assessment or another form of care is needed.</p><p>Medication may be one option, but it is not an automatic outcome of a consultation. Ask about the reasoning behind a recommendation, other approaches, and what follow-up would involve. A treatment decision should come from an appropriate clinical conversation.</p></div>`)+section('psychiatry-preparation','Before the appointment','Prepare the details that help.',rows([['Your timeline','Think about when changes began, how they affect your day, and previous periods of improvement or difficulty. Include earlier mental health care if relevant.'],['Your wider health picture','Prepare a list of medicines and supplements, relevant medical conditions, allergies, and other healthcare professionals involved. Share records only through an agreed secure process.'],['Your questions','Ask about the assessment, possible benefits and risks of treatment, monitoring, appointment frequency, and what to do if a concern arises between reviews.']]))+careComparison()+section('follow-up','Continuity of care','Agree what happens after the appointment.',tiles([['A shared understanding','Ask for an explanation of the assessment findings and the purpose of any treatment being considered. You should know what is provisional and what needs further review.'],['A review plan','Discuss what changes to notice, when follow-up is due, and whether tests or in-person examinations are needed.'],['A clear contact route','Confirm how to seek routine advice and which local service to use for urgent concerns. The website’s test enquiry form is not a clinical advice channel.']]))+faqs([['Is a psychiatrist the same as a therapist?','A psychiatrist is a medical doctor with specialist mental health training. Therapy can be offered by professionals with different qualifications. Ask about each clinician’s role, registration, and scope.'],['Is medication always prescribed?','No. A clinician decides whether medication is appropriate after assessment and discussion. A website enquiry cannot guarantee a prescription.'],['Can I have therapy alongside psychiatric care?','Discuss this with your clinicians. When useful, agree how the work and information-sharing will be coordinated with your permission.'],['Can I book or pay here?','Not yet. This website currently accepts test enquiries. Appointment arrangements, clinical delivery, and payment are not activated.']])+sources([['https://www.nimh.nih.gov/health/topics/mental-health-medications','NIMH: mental health medications']]);
 if(path==='/psychiatry/medications')return section('medicine-reading','Use the library thoughtfully','Start with the generic name.',`<div class="guide-prose two-column"><p>A medicine may have a generic name and one or more brand names. The generic name identifies the active medicine; a brand listing does not confirm local availability or make two different products interchangeable. Ask a prescriber or pharmacist about the exact product and formulation.</p><p>These guides introduce the purpose of each medicine, considerations to discuss, and sources for fuller information. They do not provide an individual recommendation, dosing plan, or a way to obtain a prescription. Suitability depends on a clinical assessment.</p></div>`)+section('medicine-groups','Understand the categories','Different medicines, different roles.',tiles([['SSRIs','Escitalopram, fluoxetine, and sertraline belong to this antidepressant group. A shared category does not mean they have identical uses or suit the same person.'],['Other antidepressants','Duloxetine is an SNRI and trazodone is a serotonin modulator. Ask why a particular option is being considered in your own care.'],['Mood and thought-related treatment','Lithium and aripiprazole have distinct roles and monitoring needs. They should not be selected by comparing a list of symptoms online.'],['Other prescription options','Buspirone and propranolol work differently and have different considerations. A clinician can explain whether either is relevant to an individual concern.']]))+section('medication-questions','For your appointment','Make room for the questions that matter.',rows([['Why this option?','Ask what treatment goal the clinician is addressing and what other approaches could be considered.'],['What should I know before starting?','Discuss unwanted effects, interactions, practical considerations, and the information that applies to your own prescription.'],['How will we follow up?','Clarify the review plan, monitoring, costs, and the route for questions. Do not change treatment using a general information page.']]))+faqs([['Are these all the medicines used in mental health care?','No. This is a selected information library, not a complete formulary or a list of medicines promised by Stillwell.'],['Do you sell or deliver medicines?','No. There is no pharmacy checkout, dispensing, or prescription delivery on this website.'],['Why are some sources from other countries?','Established public information resources help explain general concepts. Local licensing, brands, and prescribing decisions must be checked with an appropriate professional in India.']]);
 if(['/treatment','/mental-health/conditions'].includes(path))return section('using-guides',path==='/treatment'?'Care pathways':'Learning at your pace',path==='/treatment'?'A treatment plan starts with understanding.':'A condition name is a starting point.',`<div class="guide-prose two-column"><p>You may recognise parts of your experience in more than one guide. Mental health concerns can overlap, and the same symptom can have different explanations. These pages are designed to help you prepare questions, not assign a diagnosis to yourself or someone else.</p><p>Consider how long a change has been present, how much distress it causes, and which parts of everyday life it affects. A qualified professional can assess the wider picture, including physical health and current circumstances, before discussing an appropriate plan.</p></div>`)+careComparison()+section('assessment-process','From information to support','Three useful conversations.',rows([['Describe the impact','Use examples from your own life: work or study, relationships, sleep, routines, or activities you have stopped doing. You do not need medical language.'],['Understand the recommendation','Ask what the assessment suggests, what remains uncertain, and why a particular type of support is being proposed.'],['Agree how to review it','Discuss goals, follow-up, practical constraints, and how to raise concerns. A plan should be reviewed rather than treated as a one-time decision.']]))+faqs([['Can a symptom list diagnose me?','No. The examples on these pages are educational. A diagnosis requires an appropriate assessment and consideration of other explanations.'],['What if I cannot find my concern here?','You can still ask about support. These guides cover selected topics rather than every experience or condition.'],['Can I use a free screening test first?','Screening may provide a starting point for reflection, but it does not confirm or exclude a diagnosis. Read the tool’s privacy information and discuss concerns with a professional.'],['What if I need help urgently?','Do not wait for a test-form response. Immediate danger or a medical emergency needs local emergency services or the nearest emergency department.']]);
 if(path==='/resources')return section('reading-paths','Find your way in','Choose the question you have today.',rows([['“I am considering therapy.”','Start with the individual therapy guide and the help center. Explore what sessions can involve, what to ask a provider, and which practical arrangements matter to you.'],['“I want to understand an experience.”','Browse the condition guides for an overview, things to discuss, and possible care pathways. Use them to prepare a conversation rather than reach a diagnosis.'],['“I have a question about medication.”','Use the medicine library to find the generic name, discussion points, and a full source guide. Bring questions about your own prescription to a clinician or pharmacist.'],['“I want a quieter moment to reflect.”','Explore the journal or the private reflection on the assessment page. You can read without entering personal information.']]))+section('reading-well','A thoughtful way to use information','Read for clarity, not certainty.',tiles([['Notice the source','Look for named information sources and a clear distinction between general education and individual clinical advice.'],['Keep your context in view','A description may feel familiar without explaining everything. Age, health, circumstances, and other experiences all matter.'],['Turn reading into questions','Write down what you want clarified. A useful question can be more valuable than trying to decide on a label alone.']]))+section('resource-boundaries','Your information','Choose what you share.',`<div class="guide-prose"><p>The public guides and journal can be read without an administrator account. The private reflection does not save your selections. External screening websites operate under their own privacy terms, and their local support information may be designed for another country.</p><p>Stillwell’s enquiry forms currently store test contact details for administrator review. They are not a place for medical histories, patient records, or urgent concerns.</p>${a('/privacy','Read the privacy information')}</div>`)+faqs([['Is reading a guide the same as getting care?','No. The library offers general information. Assessment and treatment require an appropriate professional relationship.'],['Can I share a guide with someone?','You can share a public page link. Avoid using a guide to label someone or pressure them to disclose private experiences.'],['Where do I start if everything feels relevant?','Choose one everyday difficulty you would like to discuss and use the care enquiry route. You do not need to read the entire library first.']]);
 if(path==='/assessments')return section('screening-guide','Understand the result','A screening tool is one piece of information.',rows([['Before you begin','Check what the tool measures, who it is intended for, and whether responses are stored or shared. An external tool’s privacy policy applies when you leave Stillwell.'],['After a result','A result can suggest that a professional conversation may be useful. It is not a diagnosis, a prescription, or a decision about which treatment you need.'],['Bring questions to a clinician','Discuss your experience even if a score seems low or does not match how you feel. A clinician can look beyond a questionnaire to your wider circumstances.']]))+section('screening-topics','Explore the right information','Start with the concern, not a score.',`<div class="guide-related">${conditions.filter(c=>['depression','generalized-anxiety-disorder','attention-deficit-hyperactivity-disorder'].includes(c.slug)).map(c=>`<a href="${c.path}"><h3>${e(c.name)}</h3>${p(c.description)}<span class="text-link">Read before screening ↗</span></a>`).join('')}</div>`)+faqs([['Does Stillwell calculate a clinical score?','No. The private reflection on this page is unscored and is not a validated screening instrument. The screening link takes you to a separate service.'],['Are my reflection choices saved?','No. They are used only to display a suggested reading route on this page. Leaving or reloading the page clears the reflection.'],['Can a test rule out a mental health concern?','No. If you are worried about changes in your life, seek professional advice even if an online result does not suggest a problem.'],['Are external tests designed specifically for India?','Not necessarily. The linked resource is US-based. Language, cultural context, eligibility, privacy terms, and support pathways may differ.']]);
 if(path==='/help')return section('help-routes','Find the right route','What are you trying to do?',`<div class="guide-related">${[['Explore support','Read about therapy and psychiatry before choosing a starting point.','/services'],['Ask about a provider','Use the directory and prepare questions about qualifications and fit.','/therapists'],['Manage the journal','Authorized administrators can sign in to create, edit, and publish articles.','/admin']].map(([title,text,url])=>`<a href="${url}"><h3>${title}</h3>${p(text)}<span class="text-link">Continue ↗</span></a>`).join('')}</div>`)+section('help-expectations','Using this website','Know what happens when you click.',rows([['Care enquiries','The form collects test contact details and preferences for administrator review. A success message means the test record was saved; it does not mean an appointment is confirmed.'],['Provider applications and referrals','These forms open an administrative conversation. They do not create employment, publish a profile, transfer patient responsibility, or accept medical records.'],['Blog administration','The administrator uses email/password sign-in. Published posts are public; drafts and editing tools are restricted. Google sign-in has not been enabled.'],['Technical difficulties','If a form reports an error, check the fields and connection before trying again. Avoid sending sensitive details as a workaround. Revisit the help and privacy pages for the current testing limitations.']]))+faqs([['What does a provider’s published profile mean?','The administrator has marked the profile verified and active. You should still confirm current registration, relevant experience, fees, and availability directly before care.'],['Can I use my blog admin account as a patient account?','No. The administrator account is for publishing and website management. This website does not currently provide a patient portal.'],['Where can I find the administrator link?','Scroll to the footer and choose Administrator, or go directly to /admin. Only authorized accounts can access management features.']],'website-questions');
 if(path==='/therapists')return section('directory-guide','Beyond the search','What to look for in a provider.',rows([['Relevant qualifications','Read the profession and qualifications together. Ask what registration applies to that role and how to verify it. A job title alone does not explain every aspect of clinical scope.'],['Experience with your concerns','Ask whether the provider works with your age group and the concerns you want to discuss. The approach and training should fit the kind of support being proposed.'],['Language and practical fit','Consider whether you can speak comfortably in the offered language, whether the format is accessible, and whether the session arrangements fit your circumstances.'],['A conversation you can question','It should be possible to ask why an approach is suggested, how progress is reviewed, and what to do if the relationship does not feel useful.']]))+section('provider-questions','For an introductory conversation','Keep a few questions close.',tiles([['About the work','“How would you approach the concerns I have described, and what would we review together?”'],['About the arrangements','“What are the session length, fees, cancellation terms, and options for follow-up?”'],['About privacy','“How are records kept, what are the limits of confidentiality, and how can I contact you appropriately?”']]))+faqs([['What if no profiles match my search?','Try fewer filters or explore the service guides while you consider your options. Only profiles marked verified and published by the administrator appear here; an empty result does not establish whether suitable care is available elsewhere.'],['Does a filter confirm appointment availability?','No. Filters narrow the published information. Current availability and suitability must be confirmed separately.'],['Can I request a particular provider?','When a profile is published, its enquiry link includes the provider preference. A test enquiry is not a booking or a guarantee of acceptance.']]);
 if(path==='/get-started')return section('enquiry-expectations','Before you send','A simple enquiry, with clear boundaries.',rows([['Choose preferences, not a diagnosis','Select a service, city, language, and format. If you are unsure, choose Help me choose. No health history is needed to try this experience.'],['Use your own contact details','For adult care, enquire for yourself. For teen care, a parent or legal guardian starts the process. Professional referrals use the professional’s own contact details.'],['Review what will be stored','The review step shows your entries before submission. In testing mode, they are saved for the administrator, with no email, payment, or appointment triggered.']]))+faqs([['What happens after I submit?','The administrator can review the saved test enquiry and change its status. Automated contact, booking, and clinical services are not activated.'],['Should I describe my symptoms in detail?','No. Do not include medical records, sensitive history, or another person’s health information. Detailed clinical conversations need an agreed care process.'],['Can I book a specific time here?','No. Live scheduling is not available. The form records preferences only.'],['What if I want to change my selection before sending?','Use Back to return to an earlier step. Review the final details and the consent statement before submitting.']]);
 if(path==='/coverage')return section('cost-conversation','Before you book','Ask for the full picture.',rows([['The session itself','Confirm the consultation fee, session length, whether an initial assessment differs from follow-up, and whether taxes or other charges apply.'],['Changes to a booking','Ask about cancellation, rescheduling, late arrival, and missed-session terms. Understand these before agreeing to an appointment.'],['Other parts of care','Medicines, tests, reports, or additional professional services may have separate costs. Ask which items are included and which are not.'],['Any reimbursement','Check your own policy or benefit directly with the responsible organisation. Ask about outpatient cover, eligible providers, required documents, and whether approval is needed in advance.']]))+section('cost-records','Keep the agreement clear','Practical details worth writing down.',tiles([['The amount and what it covers','Record the agreed service, duration, fee, and any additional charges so there is a shared understanding.'],['The payment and receipt process','Ask how payment is handled and what receipt or documentation is provided. This website does not collect payment.'],['The limits of any benefit','Do not assume that an insurance logo or a service listed elsewhere applies to Stillwell. Confirm the specific arrangement.']]))+faqs([['Are Stillwell’s fees published?','Not yet. No fee schedule has been supplied for this website, so prices are not invented or implied.'],['Does Indian health insurance always cover outpatient therapy?','Do not assume coverage. Benefits and eligibility depend on the policy and circumstances; ask your insurer directly.'],['Can I use a Talkspace insurance arrangement here?','No affiliation or shared insurance arrangement is claimed. Talkspace and Stillwell are separate services.']]);
 if(['/coverage/insurance/medicare','/coverage/insurance/tricare','/nyc-teenspace'].includes(path)){const name=path.includes('medicare')?'Medicare':path.includes('tricare')?'TRICARE':'NYC Teenspace';const target=path.includes('medicare')?services[6]:path.includes('tricare')?services[4]:services[8];return section('program-context','Understand the distinction','A separate program. A different care pathway.',`<div class="guide-prose two-column">${p(name+' appears in the Talkspace reference because it relates to services or arrangements outside Stillwell’s India-focused offering. Its presence in our information library does not mean that Stillwell administers the program, verifies eligibility, or accepts its benefits.')}<p>If you are looking for care in India, start with the relevant local service information and confirm the provider’s fees and practical arrangements. If you are looking for the named external program, use its own official information and application process.</p></div>`)+section('local-care','Care in India','Explore the support relevant to you.',`<div class="guide-format"><img src="${target.image}" alt="A calm space for connection" width="600" height="450" loading="lazy"><div class="guide-prose"><h3>${e(target.name)}</h3>${p(target.description)}${p(target.expect)}${a(target.path,'Explore '+target.name.toLowerCase(),'btn')}</div></div>`)+faqs([['Does this page confirm my eligibility?', 'No. Eligibility and coverage decisions belong to the external program. Stillwell does not make those decisions.'],['Can I enter my benefit or identification number here?','No. Do not submit insurance identifiers or documents through the test enquiry form.'],['Why keep a separate information page?','It helps distinguish the external program from Stillwell’s services and gives visitors a clear route to relevant India-focused care information.']]);}
 return '';
}
export function expandCareContent(path,base){const header=base.slice(0,base.indexOf('</section>')+10);const s=services.find(x=>x.path===path),c=conditions.find(x=>x.path===path),m=medications.find(x=>x.path===path),professional=professionalPages.find(x=>x.path===path);if(s)return servicePage(s,header);if(c)return conditionPage(c,header);if(m)return medicationPage(m,header);if(professional)return professionalPage(professional,base,header);const extra=hubExtra(path);const closing=base.lastIndexOf('<section class="wrap section"><div class="care-band">');return extra?(closing>=0?base.slice(0,closing)+extra+base.slice(closing):base+extra):base;}
export function aboutExtra(){return section('our-purpose','The Stillwell approach','Make room for the whole person.',`<div class="guide-prose two-column"><p>Looking for support can begin with a practical question: who can I speak to, what will the conversation be like, and how do I know where to start? Stillwell brings service information, mental health guides, and a provider directory into one calm place to explore.</p><p>Our focus is India. Language, family context, work, accessibility, and the realities of everyday life belong in a conversation about care. The website is designed to help you ask clearer questions and find an appropriate professional starting point.</p></div>`)+section('our-principles','What should matter','Clarity, choice, and a voice in your care.',rows([['Understand the role','A service page should explain what a professional can help you explore and when another type of assessment may be needed.'],['Know who you are meeting','Provider profiles should include meaningful qualifications, relevant registration, areas of work, and practical details—not invented credentials or anonymous promises.'],['Ask about the process','You should be able to ask about goals, privacy, fees, the approach to care, and how progress will be reviewed.'],['Recognise the limits','Public information cannot replace an assessment. Test enquiries cannot book care, deliver urgent help, or become a clinical record.']]))+careComparison()+section('about-current','Where the website stands','A clear view of what is available.',`<div class="guide-prose"><p>You can explore therapy services, psychiatry and medicine information, condition guides, the journal, and the help center. The administrator can manage articles, provider profiles, and test enquiries. Provider profiles appear after verification and publication.</p><p>Live appointment scheduling, payment, patient messaging, and video sessions are not yet available through the website. Final fees, clinician profiles, business contact details, and operating policies need to be confirmed before clinical launch.</p>${a('/services','Explore care')}${a('/help','Read the help center')}</div>`);}
export function contactExtra(){return section('contact-routes','The right starting point','Choose what you would like to discuss.',`<div class="guide-related">${[['Care preferences','Use the step-by-step test enquiry for service, location, language, and session preferences.','/get-started'],['Professional introductions','Introduce your own qualifications or ask about joining the provider directory.','/join-our-network/therapist'],['Partnerships and organisations','Start an organisational conversation without sharing employee, student, or patient records.','/partners/health-collective']].map(([title,text,url])=>`<a href="${url}"><h3>${title}</h3>${p(text)}<span class="text-link">Continue ↗</span></a>`).join('')}</div>`)+faqs([['Does this contact preview send an email?','No. The contact preview validates locally and does not store or deliver your message. The separate care enquiry form saves test details to the administrator portal.'],['Can I send medical documents?','No. Please do not include medical records, identification documents, or another person’s private information.'],['Where are your telephone number and clinic address?','Confirmed business contact details and clinic locations have not yet been supplied. We have not added invented addresses or phone numbers.'],['What if my situation is urgent?','This website is not monitored as an emergency service. Contact local emergency services or the nearest emergency department for immediate danger or a medical emergency.']]);}
export function journalExtra(){return section('journal-paths','Reading with a purpose','Follow the question that brought you here.',rows([['Starting therapy','Explore the individual therapy guide, how to prepare for a conversation, and the questions you can ask about a provider’s approach.'],['Understanding an experience','Use the condition library to learn the language of a concern and prepare for assessment. A guide is not a diagnosis.'],['Relationships and everyday life','Browse stories about communication, boundaries, transitions, and making space to reflect. Choose what feels relevant without needing to finish everything.']]))+`<section class="wrap guide-actions">${a('/online-therapy','Starting therapy')}${a('/mental-health/conditions','Condition guides')}${a('/online-therapy/couples-therapy','Relationship support')}</section>`;}
export function privacyExtra(){return section('privacy-detail','Website privacy in testing','Understand what is public and what is private.',rows([['Public pages and profiles','Published journal posts, uploaded published images, service information, and verified active provider profiles are available to visitors. Do not publish information through the administrator portal unless it is intended to be public.'],['Administrator access','Authorized administrators sign in through Supabase Auth. The browser stores the session for sign-in continuity. Draft posts, provider management, and enquiry records are restricted by database access rules.'],['Test form submissions','Care and professional enquiry records include the contact details, preferences, professional introduction if entered, and consent supplied in the form. Administrators can review them; no automatic email or appointment is triggered.'],['Reflection and external resources','The private reflection does not save its selections. External websites, including screening resources, have their own terms and privacy practices. Review those before entering information.'],['Before collecting real care information','Final business identity, privacy contact, retention arrangements, user rights processes, clinical consent, and records handling need to be established before this website accepts real clinical information. This testing notice is not a complete clinical-service privacy policy.']]));}
